import React, { useState, useRef, useEffect } from 'react';
import './App.css';

function App() {
  const [files, setFiles] = useState([]);
  const [uploadedFiles, setUploadedFiles] = useState([]);
  const [question, setQuestion] = useState('');
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [totalChunks, setTotalChunks] = useState(0);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    loadFiles();
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const loadFiles = async () => {
    try {
      const res = await fetch('http://localhost:8000/files');
      const data = await res.json();
      setUploadedFiles(data.files || []);
      setTotalChunks(data.total_chunks);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleFileSelect = (e) => {
    const selectedFiles = Array.from(e.target.files);
    setFiles(prev => [...prev, ...selectedFiles]);
  };

  const removeFile = (index) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const uploadFiles = async () => {
    if (files.length === 0) {
      alert('Select files first');
      return;
    }

    setLoading(true);
    
    for (let file of files) {
      const formData = new FormData();
      formData.append('file', file);
      
      addMessage('system', `📤 Uploading ${file.name}...`);
      
      try {
        const res = await fetch('http://localhost:8000/upload', {
          method: 'POST',
          body: formData
        });
        const data = await res.json();
        
        if (res.ok) {
          addMessage('system', `✅ ${file.name} (${data.chunks} chunks)`);
        } else {
          addMessage('system', `❌ ${file.name} failed`);
        }
      } catch (err) {
        addMessage('system', `❌ ${file.name} failed`);
      }
    }
    
    setFiles([]);
    await loadFiles();
    setLoading(false);
    addMessage('system', `✨ Total: ${totalChunks} chunks`);
  };

  const askQuestion = async () => {
    if (!question.trim()) return;
    
    const userQuestion = question;
    setQuestion('');
    addMessage('user', userQuestion);
    setLoading(true);
    
    try {
      const res = await fetch(`http://localhost:8000/ask?question=${encodeURIComponent(userQuestion)}`, {
        method: 'POST'
      });
      const data = await res.json();
      
      if (data.error) {
        addMessage('bot', `❌ ${data.error}`);
      } else {
        addMessage('bot', data.answer);
        if (data.sources && data.sources.length > 0) {
          const sources = data.sources.map(s => s.file).join(', ');
          addMessage('system', `📚 Source: ${sources}`);
        }
      }
    } catch (err) {
      addMessage('bot', '❌ Backend not running');
    }
    setLoading(false);
  };

  const addMessage = (role, content) => {
    setMessages(prev => [...prev, { role, content, id: Date.now() }]);
  };

  const clearChat = () => {
    setMessages([]);
  };

  const clearAll = async () => {
    if (confirm('Delete all files?')) {
      await fetch('http://localhost:8000/clear', { method: 'DELETE' });
      await loadFiles();
      addMessage('system', '🗑️ All cleared');
    }
  };

  const getFileIcon = (type) => {
    const icons = { pdf: '📄', docx: '📝', txt: '📃', csv: '📊', xlsx: '📈', json: '🔧' };
    return icons[type] || '📄';
  };

  return (
    <div className="app">
      {/* Header */}
      <header>
        <div className="logo">
          <span className="logo-icon">◆</span>
          <span className="logo-text">DOCUMENT CHAT</span>
        </div>
        <div className="stats">
          <span className="stat">{uploadedFiles.length} files</span>
          <span className="stat">{totalChunks} chunks</span>
        </div>
      </header>

      {/* Main Content */}
      <main>
        {/* Upload Section */}
        <section className="upload-section">
          <div className="section-title">
            <span className="title-icon">↓</span>
            <h2>Upload Documents</h2>
          </div>
          <p className="section-desc">PDF · DOCX · TXT · CSV · Excel · JSON</p>
          
          <div className="upload-area">
            <input 
              type="file" 
              accept=".pdf,.docx,.txt,.csv,.xlsx,.json" 
              onChange={handleFileSelect}
              multiple
              id="file-input"
              hidden
            />
            <label htmlFor="file-input" className="upload-btn">
              + Select Files
            </label>
            
            {files.length > 0 && (
              <div className="file-list">
                {files.map((file, idx) => (
                  <div key={idx} className="file-item">
                    <span>{getFileIcon(file.name.split('.').pop())}</span>
                    <span className="file-name">{file.name}</span>
                    <button className="remove-btn" onClick={() => removeFile(idx)}>×</button>
                  </div>
                ))}
                <button className="upload-submit" onClick={uploadFiles} disabled={loading}>
                  {loading ? 'Uploading...' : `Upload ${files.length} files`}
                </button>
              </div>
            )}
          </div>
          
          {uploadedFiles.length > 0 && (
            <div className="uploaded-list">
              <div className="list-header">
                <span>📁 Uploaded</span>
                <button className="clear-all" onClick={clearAll}>Clear all</button>
              </div>
              <div className="file-grid">
                {uploadedFiles.map((file, idx) => (
                  <div key={idx} className="uploaded-item">
                    <span>{getFileIcon(file.type)}</span>
                    <span className="file-name">{file.name}</span>
                    <span className="chunks">{file.chunks}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </section>

        {/* Chat Section */}
        <section className="chat-section">
          <div className="section-title">
            <span className="title-icon">◆</span>
            <h2>Ask Questions</h2>
            <button className="clear-chat" onClick={clearChat}>Clear</button>
          </div>
          
          <div className="messages-container">
            {messages.length === 0 ? (
              <div className="welcome">
                <p>◆ Upload documents to get started</p>
                <div className="examples">
                  <button onClick={() => setQuestion("Summarize this document")}>Summarize</button>
                  <button onClick={() => setQuestion("What are the main points?")}>Key points</button>
                  <button onClick={() => setQuestion("List important information")}>List all</button>
                </div>
              </div>
            ) : (
              messages.map((msg) => (
                <div key={msg.id} className={`message ${msg.role}`}>
                  <div className="message-icon">
                    {msg.role === 'user' ? '◆' : msg.role === 'bot' ? '●' : '○'}
                  </div>
                  <div className="message-content">{msg.content}</div>
                </div>
              ))
            )}
            {loading && <div className="typing">● thinking...</div>}
            <div ref={messagesEndRef} />
          </div>

          <div className="input-area">
            <textarea
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && !e.shiftKey && askQuestion()}
              placeholder="Ask about your documents..."
              rows="1"
            />
            <button onClick={askQuestion} disabled={loading || totalChunks === 0}>
              Send →
            </button>
          </div>
        </section>
      </main>
    </div>
  );
}

export default App;
